```c
#include <stdio.h>

int main() {
    int opcion;
    double a, b, resultado;

    do {
        printf("\n=== CALCULADORA ===\n");
        printf("1. Suma\n");
        printf("2. Resta\n");
        printf("3. Multiplicacion\n");
        printf("4. Division\n");
        printf("5. Salir\n");
        printf("Elige una opcion: ");
        scanf("%d", &opcion);

        if (opcion >= 1 && opcion <= 4) {
            printf("Ingresa el primer numero: ");
            scanf("%lf", &a);
            printf("Ingresa el segundo numero: ");
            scanf("%lf", &b);
        }

        switch (opcion) {
            case 1:
                resultado = a + b;
                printf("Resultado: %.2f\n", resultado);
                break;
            case 2:
                resultado = a - b;
                printf("Resultado: %.2f\n", resultado);
                break;
            case 3:
                resultado = a * b;
                printf("Resultado: %.2f\n", resultado);
                break;
            case 4:
                if (b == 0) {
                    printf("Error: no se puede dividir entre cero.\n");
                } else {
                    resultado = a / b;
                    printf("Resultado: %.2f\n", resultado);
                }
                break;
            case 5:
                printf("Hasta luego.\n");
                break;
            default:
                printf("Opcion invalida.\n");
        }

    } while (opcion != 5);  // <-- punto y coma obligatorio aqui

    return 0;
}
```

Observa que la verificación de división entre cero está dentro del `case 4`, justo antes de calcular. Si `b == 0`, se imprime el error y no se hace la operación. El bucle continúa normalmente.

